def calculate_S(N):
    S = 0
    N_plus_1 = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // N_plus_1
    return S

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

N_values = [1, 2, 3, 4]
results = {}
for N in N_values:
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    results[N] = {'S(N)': S_N, 'T(N)': T_N, 'Match': S_N == T_N}

for N, res in results.items():
    print(f"N={N}: S(N) = {res['S(N)']}, T(N) = {res['T(N)']}, Match = {res['Match']}")

def calculate_R(N):
    M = N + 1
    R = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            fractional_part = (a * b) / M - int((a * b) / M)
            R += fractional_part
    return R

R3 = calculate_R(3)
print(f"R(3) calculated by code: {R3}")
